function elementBars(values, label) {
  const max = Math.max(...Object.values(values));
  return `<figure class="element-chart"><figcaption>${label}</figcaption>${Object.entries(values).map(([name, value]) => `<div class="bar-row"><strong>${name}</strong><span class="bar-track"><i style="width:${Math.round(value / max * 100)}%"></i></span><b>${value}</b></div>`).join('')}</figure>`;
}

